CREATE OR REPLACE PROCEDURE public.sp_update_branch_floor_map(IN p_id uuid, IN p_tenant_id uuid, IN p_name character varying, IN p_building_area character varying, IN p_floor_level character varying, IN p_description text, IN p_file_storage_key character varying, IN p_file_type character varying, IN p_file_size bigint, IN p_content_hash character varying, IN p_version integer, IN p_status character varying, IN p_review_due_at timestamp with time zone, IN p_published_by character varying, IN p_published_at timestamp with time zone, IN p_supersedes_map_id uuid, IN p_emergency_instructions text)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE branch_floor_maps SET         name = p_name,         building_area = p_building_area,         floor_level = p_floor_level,         description = p_description,         file_storage_key = p_file_storage_key,         file_type = p_file_type,         file_size = p_file_size,         content_hash = p_content_hash,         version = p_version,         status = p_status,         review_due_at = p_review_due_at,         published_by = p_published_by,         published_at = p_published_at,         supersedes_map_id = p_supersedes_map_id,         row_version = row_version + 1,         emergency_instructions = p_emergency_instructions     WHERE tenant_id = p_tenant_id AND id = p_id; END; $procedure$ ;
